package com.lanremote.bluetooth;
import android.app.*;
import android.content.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.util.*;

final class TvRemote {
 private final Activity activity;private final boolean restricted;private final TvProfiles profiles;private TvProfile profile;private final boolean fixed;private final LinearLayout panel,driverPanel;
 private final Handler main=new Handler(Looper.getMainLooper());private TvPlatform platform;private String ip;private LgRemote lg;private SamsungRemote samsung;private RokuRemote roku;private AndroidTvRemote androidTv;private SonyRemote sony;
 private TextView mirror;private Runnable observer,keyboardObserver;private boolean active,selected,disposed,discovering,switching,recovering;private int recoveryGeneration;private long nextRecovery;private String status="Select a TV platform.";
 private final Runnable idle=this::restDrivers;
 TvRemote(Activity a,LinearLayout parent){this(a,parent,false);}
 TvRemote(Activity a,LinearLayout parent,boolean restricted){this(a,parent,restricted,null);}
 TvRemote(Activity a,LinearLayout parent,boolean restricted,TvProfile target){activity=a;this.restricted=restricted;fixed=target!=null;profiles=new TvProfiles(a);profile=fixed?target:profiles.selected();platform=profile==null?TvPlatform.NONE:profile.platform;ip=profile==null?"":profile.ip;
  panel=new LinearLayout(a);panel.setOrientation(LinearLayout.VERTICAL);parent.addView(panel);panel.setVisibility(View.GONE);
  if(!restricted){Button choose=new RemoteButton(a);choose.setText("Saved TVs / add TV");choose.setAllCaps(false);choose.setOnClickListener(v->manage());panel.addView(choose,new LinearLayout.LayoutParams(-1,RemoteTheme.dp(a,48)));}
  driverPanel=new LinearLayout(a);driverPanel.setOrientation(LinearLayout.VERTICAL);panel.addView(driverPanel);
  // Existing LG users retain their settings; drivers do not open network connections until used.
  if(platform==TvPlatform.LG)ensureDriver();
  else status=platform==TvPlatform.NONE?"Select a TV platform.":platform.label+" • select TV to connect.";
 }
 private void ensureDriver(){if(disposed)return;if(platform==TvPlatform.LG&&lg==null){lg=new LgRemote(activity,driverPanel,restricted,ip);if(mirror!=null)lg.setMirrorStatus(mirror);lg.setObserver(()->{if(lg!=null)maybeRecover(lg.connectionStatus());notifyObserver();});lg.setKeyboardFocusObserver(()->{if(keyboardObserver!=null)keyboardObserver.run();});lg.visible(selected);}
  if(platform==TvPlatform.SAMSUNG&&samsung==null&&!ip.isEmpty()){samsung=new SamsungRemote(activity,ip,restricted,this::message);if(!restricted){Button connect=new RemoteButton(activity);connect.setText("Connect / pair Samsung");connect.setAllCaps(false);connect.setOnClickListener(v->connect());driverPanel.addView(connect);Button forget=new RemoteButton(activity);forget.setText("Forget Samsung pairing");forget.setAllCaps(false);forget.setOnClickListener(v->new AlertDialog.Builder(activity).setMessage("Forget this TV's saved certificate and pairing token?").setPositiveButton("Forget",(d,w)->samsung.forget()).setNegativeButton("Cancel",null).show());driverPanel.addView(forget);}}
  if(platform==TvPlatform.ROKU&&roku==null&&!ip.isEmpty()){roku=new RokuRemote(activity,ip,this::message);if(!restricted){TextView hint=new TextView(activity);hint.setText("Experimental Roku local control. On your Roku set Control by mobile apps to Enabled. Local HTTP is unencrypted; use trusted home Wi-Fi. Roku discourages third-party remote apps.");RemoteTheme.secondary(hint);driverPanel.addView(hint);Button connect=new RemoteButton(activity);connect.setText("Connect / authorize Roku");connect.setAllCaps(false);connect.setOnClickListener(v->connect());driverPanel.addView(connect);Button forget=new RemoteButton(activity);forget.setText("Forget Roku authorization");forget.setAllCaps(false);forget.setOnClickListener(v->{if(roku!=null)roku.forget();});driverPanel.addView(forget);}}
  if(platform==TvPlatform.ANDROID&&androidTv==null&&!ip.isEmpty()){androidTv=new AndroidTvRemote(activity,ip,restricted,this::message);if(!restricted){Button pair=new RemoteButton(activity);pair.setText("Connect / pair Android TV");pair.setAllCaps(false);pair.setOnClickListener(v->connect());driverPanel.addView(pair);Button forget=new RemoteButton(activity);forget.setText("Forget Android TV pairing");forget.setAllCaps(false);forget.setOnClickListener(v->{if(androidTv!=null)androidTv.forget();});driverPanel.addView(forget);}}
  if(platform==TvPlatform.SONY&&sony==null&&!ip.isEmpty()){sony=new SonyRemote(activity,ip,restricted,this::message);if(!restricted){Button pair=new RemoteButton(activity);pair.setText("Configure Sony IP control");pair.setAllCaps(false);pair.setOnClickListener(v->sony.setup());driverPanel.addView(pair);Button reconnect=new RemoteButton(activity);reconnect.setText("Reconnect Sony");reconnect.setAllCaps(false);reconnect.setOnClickListener(v->sony.connect(true));driverPanel.addView(reconnect);Button forget=new RemoteButton(activity);forget.setText("Forget Sony key");forget.setAllCaps(false);forget.setOnClickListener(v->{if(sony!=null)sony.forget();});driverPanel.addView(forget);}}
 }
 private void notifyObserver(){if(!switching&&observer!=null)observer.run();}
 private void message(String value){status=value;if(mirror!=null)mirror.setText("TV: "+value);if(!switching)maybeRecover(value);notifyObserver();}
 void setMirrorStatus(TextView v){mirror=v;if(lg!=null)lg.setMirrorStatus(v);else message(status);}
 void setObserver(Runnable r){observer=r;}
 void setKeyboardFocusObserver(Runnable r){keyboardObserver=r;}
 String profileId(){return profile==null?"":profile.id;}
 String deviceLabel(){TvProfile current=profiles.get(profileId());if(current!=null&&!current.name.isEmpty())return current.name;if(lg!=null)return lg.deviceLabel();if(roku!=null)return roku.label();if(platform==TvPlatform.LG)return "LG TV";return platform==TvPlatform.NONE?"Set up TV":platform.label+" • "+ip;}
 void visible(boolean show){selected=show;panel.setVisibility(show&&!restricted?View.VISIBLE:View.GONE);if(show)ensureDriver();if(lg!=null)lg.visible(show);}
 private void cancelRecovery(){recoveryGeneration++;recovering=false;}
 private void maybeRecover(String reason){if(TvRecoveryPolicy.failure(reason))recover(false);}
 void networkChanged(){if(active&&selected&&!ready(false))recover(false);}
 private void recover(boolean force){if(disposed||switching||!active||!selected||profile==null||recovering||ready(false)||(!force&&SystemClock.elapsedRealtime()<nextRecovery))return;TvProfile target=profile;String pin=TvRecovery.pin(activity,target);if(pin.isEmpty())return;try{RelayNetwork.wifi(activity);}catch(Exception e){return;}recovering=true;nextRecovery=SystemClock.elapsedRealtime()+TvRecoveryPolicy.COOLDOWN;int token=++recoveryGeneration;new Thread(()->{String found="";try{found=TvRecovery.find(activity.getApplicationContext(),target,pin);}catch(Exception ignored){}String address=found;main.post(()->{if(disposed||token!=recoveryGeneration)return;recovering=false;if(!active||!selected||ready(false)||!TvProfile.sameEndpoint(profile,target)||address.isEmpty())return;if(!TvRecovery.move(activity,profiles,target,address,pin))return;TvProfile moved=profiles.get(target.id);if(fixed){notifyObserver();return;}replaceDriver(moved,false);message("Verified TV address updated to "+address+". Reconnecting…");});},"tv-recovery").start();}
 void resumeForeground(){resumeForeground(true);}
 void resumeForeground(boolean tv){active=true;selected=tv;if(platform==TvPlatform.LG){ensureDriver();lg.resumeForeground(tv);}else if(tv){ensureDriver();if(samsung!=null)samsung.connect(false);if(roku!=null)roku.connect();if(androidTv!=null)androidTv.connect(false);if(sony!=null)sony.connect(false);}}
 void controlMode(boolean tv){selected=tv;if(!tv)cancelRecovery();main.removeCallbacks(idle);if(!active)return;if(tv){ensureDriver();if(lg!=null)lg.controlMode(true);else if(samsung!=null)samsung.connect(false);else if(roku!=null)roku.connect();else if(androidTv!=null)androidTv.connect(false);else if(sony!=null)sony.connect(false);}else{if(lg!=null)lg.controlMode(false);if(samsung!=null||roku!=null||androidTv!=null||sony!=null)main.postDelayed(idle,IdlePolicy.TV_IDLE);}}
 private void restDrivers(){if(!selected&&samsung!=null)samsung.disconnect("Samsung connection resting.");if(!selected&&roku!=null)roku.disconnect("Roku resting.");if(!selected&&androidTv!=null)androidTv.disconnect("Android TV resting.");if(!selected&&sony!=null)sony.disconnect("Sony resting.");}
 void suspendForeground(){active=false;cancelRecovery();main.removeCallbacks(idle);if(lg!=null)lg.suspendForeground();if(samsung!=null)samsung.disconnect("Samsung connection resting.");if(roku!=null)roku.disconnect("Roku resting.");if(androidTv!=null)androidTv.disconnect("Android TV resting.");if(sony!=null)sony.disconnect("Sony resting.");}
 void destroy(){disposed=true;cancelRecovery();main.removeCallbacksAndMessages(null);if(lg!=null)lg.destroy();if(samsung!=null)samsung.destroy();if(roku!=null)roku.destroy();if(androidTv!=null)androidTv.destroy();if(sony!=null)sony.destroy();}
 private void manage(){if(restricted||!active||disposed)return;List<TvProfile> saved=profiles.all();ArrayList<String> labels=new ArrayList<>();for(TvProfile p:saved)labels.add((p.id.equals(profileId())?"✓ ":"")+p.label()+" ("+p.ip+")");labels.add("Add TV");if(profile!=null){labels.add("Rename selected TV");labels.add("Rediscover selected TV");labels.add("Remove selected TV");}new AlertDialog.Builder(activity).setTitle("Saved TVs").setItems(labels.toArray(new String[0]),(d,i)->{if(i<saved.size()){activate(saved.get(i),true);return;}if(i==saved.size()){choose();return;}if(i==saved.size()+1)rename();else if(i==saved.size()+2){if(TvRecovery.pin(activity,profile).isEmpty())new AlertDialog.Builder(activity).setMessage("This TV does not have a verified secure identity for automatic address migration. Add its new address and authorize it explicitly.").setPositiveButton("OK",null).show();else if(ready(false))message("TV is already connected.");else{message("Checking saved TV identity on local Wi-Fi…");recover(true);}}else remove();}).setNegativeButton("Cancel",null).show();}
 private void rename(){if(profile==null)return;String id=profile.id;EditText name=new EditText(activity);name.setSingleLine(true);name.setText(profile.name);name.setHint("Living room TV");name.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(40)});new AlertDialog.Builder(activity).setTitle("TV nickname").setView(name).setPositiveButton("Save",(d,w)->{profiles.rename(id,name.getText().toString());if(id.equals(profileId()))profile=profiles.get(id);notifyObserver();}).setNegativeButton("Cancel",null).show();}
 private void remove(){if(profile==null)return;String id=profile.id;new AlertDialog.Builder(activity).setTitle("Remove saved TV?").setMessage("Removes the profile and resets volume routing if it targets this TV. Existing pairing records remain in the driver; use Forget pairing first if desired.").setPositiveButton("Remove",(d,w)->{if(!id.equals(profileId()))return;profiles.remove(id);activate(profiles.selected(),false);}).setNegativeButton("Cancel",null).show();}
 private void choose(){if(restricted||!active||discovering)return;new AlertDialog.Builder(activity).setTitle("TV platform").setItems(new String[]{"Discover on Wi-Fi","LG webOS","Samsung Tizen","Roku (experimental)","Android / Google TV","Fire TV (not yet supported)","VIDAA (not yet supported)","Sony BRAVIA IP","Philips Saphi / Titan OS (not yet supported)","Apple TV (not yet supported)"},(d,i)->{if(i==0)discover();else manual(TvPlatform.values()[i-1]);}).setNegativeButton("Cancel",null).show();}
 private void manual(TvPlatform p){if(p==TvPlatform.FIRE||p==TvPlatform.VIDAA||p==TvPlatform.PHILIPS||p==TvPlatform.APPLE){new AlertDialog.Builder(activity).setMessage(p.label+" identified. Native control is not available yet. Your existing TV configuration is unchanged.").setPositiveButton("OK",null).show();return;}EditText field=new EditText(activity);field.setSingleLine(true);field.setInputType(android.text.InputType.TYPE_CLASS_PHONE);field.setHint("TV private IPv4 address");if(platform==p)field.setText(ip);AlertDialog d=new AlertDialog.Builder(activity).setTitle(p.label).setView(field).setPositiveButton("Select",null).setNegativeButton("Cancel",null).create();d.setOnShowListener(v->d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(w->{String address=field.getText().toString().trim();if(!RelayWire.privateIP(address)){field.setError("Enter a private IPv4 address");return;}d.dismiss();switchTo(p,address);}));d.show();}
 private void discover(){discovering=true;message("Looking for TV platforms…");new Thread(()->{try{java.util.concurrent.FutureTask<List<TvDiscovery.Found>> atv=new java.util.concurrent.FutureTask<>(()->AtvDiscovery.find(activity.getApplicationContext()));new Thread(atv,"atv-discovery").start();List<TvDiscovery.Found> list=new ArrayList<>();try{list.addAll(TvDiscovery.find(activity.getApplicationContext()));}catch(Exception ignored){}try{list.addAll(atv.get(6,java.util.concurrent.TimeUnit.SECONDS));}catch(Exception ignored){}main.post(()->{discovering=false;if(disposed||!active)return;if(list.isEmpty()){message("No advertised TV platforms found. Select manually.");return;}String[] labels=new String[list.size()];for(int i=0;i<labels.length;i++)labels[i]=list.get(i).label();new AlertDialog.Builder(activity).setTitle("Choose your TV").setItems(labels,(d,i)->{TvDiscovery.Found item=list.get(i);switchTo(item.platform,item.ip);}).setNegativeButton("Cancel",null).show();});}catch(Exception e){main.post(()->{discovering=false;if(!disposed&&active)message("TV discovery unavailable. Select manually.");});}},"tv-discovery").start();}
 private void switchTo(TvPlatform p,String address){if(!active||restricted)return;try{activate(profiles.add(p,address),true);}catch(RuntimeException e){message(e.getMessage());}}
 private void activate(TvProfile next,boolean save){if(disposed||fixed||restricted)return;replaceDriver(next,save);}
 private void replaceDriver(TvProfile next,boolean save){if(disposed)return;if(next!=null&&profile!=null&&next.id.equals(profile.id)&&next.ip.equals(profile.ip)){if(save)profiles.select(next.id);controlMode(true);notifyObserver();return;}cancelRecovery();nextRecovery=0;switching=true;main.removeCallbacks(idle);if(lg!=null){lg.setObserver(null);lg.destroy();lg=null;}if(samsung!=null){samsung.destroy();samsung=null;}if(roku!=null){roku.destroy();roku=null;}if(androidTv!=null){androidTv.destroy();androidTv=null;}if(sony!=null){sony.destroy();sony=null;}driverPanel.removeAllViews();profile=next;platform=next==null?TvPlatform.NONE:next.platform;ip=next==null?"":next.ip;if(save&&next!=null)profiles.select(next.id);TvPlatform p=platform;ensureDriver();switching=false;if(lg!=null){lg.visible(panel.getVisibility()==View.VISIBLE);lg.resumeForeground(selected);}else if(p==TvPlatform.NONE)message("Add a TV to get started.");else if(p==TvPlatform.ROKU)message("Roku selected. Open Connect / authorize Roku.");else if(p==TvPlatform.ANDROID)message("Android TV selected. Open Connect / pair Android TV.");else if(p==TvPlatform.SONY)message("Sony selected. Configure the TV’s IP control key.");else message("Samsung TV selected. Connect / pair to approve.");if(selected&&active&&lg==null)controlMode(true);notifyObserver();}
 void connect(){ensureDriver();if(lg!=null)lg.connect();else if(samsung!=null)samsung.connect(!restricted);else if(androidTv!=null)androidTv.connect(!restricted);else if(sony!=null){if(sony.configured())sony.connect(!restricted);else if(!restricted)sony.setup();}else if(roku!=null){if(roku.configured()){if(restricted)roku.connect();else roku.reconnect();}else if(!restricted)new AlertDialog.Builder(activity).setTitle("Authorize local Roku control?").setMessage("Only select your own Roku on trusted home Wi-Fi. Roku requires Control by mobile apps = Enabled and discourages third-party apps. This protocol is unencrypted. LANremote will not bypass denied commands.").setPositiveButton("Authorize",(d,w)->{if(active&&roku!=null)roku.authorize();}).setNegativeButton("Cancel",null).show();}else message("Select a supported TV first.");}
 boolean sessionConfigured(){if(lg!=null)return lg.sessionConfigured();if(platform==TvPlatform.SAMSUNG){ensureDriver();return samsung!=null&&samsung.configured();}if(platform==TvPlatform.ROKU){ensureDriver();return roku!=null&&roku.configured();}if(platform==TvPlatform.ANDROID){ensureDriver();return androidTv!=null&&androidTv.configured();}if(platform==TvPlatform.SONY){ensureDriver();return sony!=null&&sony.configured();}return false;}
 boolean sessionCanWake(){return lg!=null&&lg.sessionCanWake();}
 void sessionWake(){if(lg!=null)lg.sessionWake();}
 void sessionOff(){if(lg!=null)lg.sessionOff();else if(samsung!=null)samsung.action("powerOff");else if(roku!=null)roku.action("powerOff");else if(androidTv!=null)androidTv.action("powerOff");else if(sony!=null)sony.action("powerOff");}
 boolean ready(boolean pointer){return lg!=null?lg.ready(pointer):samsung!=null&&samsung.ready()||roku!=null&&roku.ready()||androidTv!=null&&androidTv.ready()||sony!=null&&sony.ready();}
 boolean supports(String action){if(platform==TvPlatform.LG)return true;if(platform==TvPlatform.ROKU)return roku!=null&&roku.supports(action);if(platform==TvPlatform.ANDROID)return androidTv!=null&&androidTv.supports(action);if(platform==TvPlatform.SONY)return sony!=null&&sony.supports(action);if(platform==TvPlatform.SAMSUNG)return "playPause".equals(action)||!TvPlatform.samsungKey(action).isEmpty();return false;}
 boolean pointerAvailable(){return lg!=null&&lg.ready(true);}
 void movePointer(int x,int y){if(lg!=null)lg.movePointer(x,y);}
 void remoteAction(String action){if(lg!=null)lg.remoteAction(action);else if(samsung!=null){if("playPause".equals(action)){new AlertDialog.Builder(activity).setTitle("Playback").setItems(new String[]{"Play","Pause"},(d,i)->samsung.action(i==0?"PLAY":"PAUSE")).show();}else samsung.action(action);}else if(roku!=null)roku.action(action);else if(androidTv!=null)androidTv.action(action);else if(sony!=null){if("playPause".equals(action)){ArrayList<String> choices=new ArrayList<>();if(sony.supports("PLAY"))choices.add("Play");if(sony.supports("PAUSE"))choices.add("Pause");if(!choices.isEmpty())new AlertDialog.Builder(activity).setTitle("Playback").setItems(choices.toArray(new String[0]),(d,i)->{if(sony!=null)sony.action(choices.get(i).toUpperCase(Locale.ROOT));}).show();}else sony.action(action);}}
 void keyboard(){if(lg!=null)lg.keyboard();}
 void openLiveKeyboard(boolean auto){if(lg!=null)lg.openLiveKeyboard(auto);}
 void closeLiveKeyboard(){if(lg!=null)lg.closeLiveKeyboard();}
 void quickSettings(){if(lg!=null)lg.quickSettings();else remoteAction("MENU");}
 void pictureModes(){if(lg!=null)lg.pictureModes();else quickSettings();}
 void quickHdmi(int n){if(lg!=null)lg.quickHdmi(n);else if(sony!=null&&n>=1&&n<=3){if(sony.ready()&&sony.supports("HDMI"+n))sony.action("HDMI"+n);else message("Sony HDMI command not advertised.");}else if(androidTv!=null&&n>=1&&n<=3){if(androidTv.ready())androidTv.action("HDMI"+n);else message("Select Android TV and connect first.");}else if(roku!=null&&n>=1&&n<=3){if(roku.ready()&&roku.supports("HDMI"+n))roku.action("HDMI"+n);else message("Roku HDMI control unavailable on this device.");}else if(samsung!=null&&n>=1&&n<=3){if(samsung.ready())samsung.action("HDMI"+n);else message("Select Samsung TV and connect first.");}}
 void powerDialog(){if(lg!=null)lg.powerDialog();else if(sony!=null&&sony.ready()&&sony.supports("powerOff"))new AlertDialog.Builder(activity).setTitle("Sony power").setMessage("Turn the TV off? Network power-on is not implemented.").setPositiveButton("Power off",(d,w)->{if(sony!=null)sony.action("powerOff");}).setNegativeButton("Cancel",null).show();else if(androidTv!=null&&androidTv.ready())new AlertDialog.Builder(activity).setTitle("Android TV power").setMessage("Put the television to sleep? Network power-on is not implemented.").setPositiveButton("Sleep",(d,w)->{if(androidTv!=null)androidTv.action("powerOff");}).setNegativeButton("Cancel",null).show();else if(roku!=null&&roku.ready()&&roku.supports("powerOff"))new AlertDialog.Builder(activity).setTitle("Roku power").setMessage("Turn the TV off? Network power-on is not supported.").setPositiveButton("Power off",(d,w)->{if(roku!=null)roku.action("powerOff");}).setNegativeButton("Cancel",null).show();else if(samsung!=null&&samsung.ready())new AlertDialog.Builder(activity).setTitle("Samsung TV power").setMessage("Turn the TV off? Network power-on is not supported yet.").setPositiveButton("Power off",(d,w)->samsung.action("powerOff")).setNegativeButton("Cancel",null).show();else message("Select and connect a supported TV first.");}
}
